INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f1836e9e-8970-5aca-add7-39c04e41e878'::uuid, '01ee9428-38a2-5728-9fea-45675b1b219b'::uuid, 'CABLE INFO U/UTP CAT6 NEXANS', 'CABLE INFO U/UTP CAT6 LANmark-6 AWG23 . 4PAIRE LSZH ORANGE 500M . NEXANS', 'Cables & wiring', NULL, NULL, 7.5, 'MAD', 'Rouleau', '500 m²', 'https://lechantier.ma/uploads/media/da2f334519f6.webp', $j$["https://lechantier.ma/uploads/media/da2f334519f6.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/cablage-electrique/cable-info-u-utp-cat6-nexans", "category_fr": "Cables & wiring", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Compliant with all Category 6 cable standardsSupports Class E applicationsCentral cross member maintains geometry and performanceTested up to 350MHzEnhanced reaction-to-fire performance according to CPR classification Cca-s1a,d1,a1 (h/EN50575:2014+A1:2016)DESCRIPTIONAPPLICATIONNexans LANmark-6 cables are the ideal solution for most of today’s network requirements in normal office environments. They are manufactured and tested to the latest Category 6 specifications defined in the International and American cable standards and are designed to meet the quality and performance criteria needed to support all applications up to 250 MHz.10baseT Ethernet100baseTX Fast Ethernet1000baseTX Gigabit Ethernet155 MBit ATM622 MBit ATM1.2 Gbit ATMFuture class E applicationsDESIGNThe LANmark-6 U/UTP cables have a central cross element which helps maintaining the stability of the cable geometry and reduces the risk of a reduction in performance when bending the cable.", "technical_specifications_original": "• Compliant with all Category 6 cable standardsSupports Class E applicationsCentral cross member maintains geometry and performanceTested up to 350MHzEnhanced reaction-to-fire performance according to CPR classification Cca-s1a,d1,a1 (h/EN50575:2014+A1:2016)DESCRIPTIONAPPLICATIONNexans LANmark-6 cables are the ideal solution for most of today’s network requirements in normal office environments. They are manufactured and tested to the latest Category 6 specifications defined in the International and American cable standards and are designed to meet the quality and performance criteria needed to support all applications up to 250 MHz.10baseT Ethernet100baseTX Fast Ethernet1000baseTX Gigabit Ethernet155 MBit ATM622 MBit ATM1.2 Gbit ATMFuture class E applicationsDESIGNThe LANmark-6 U/UTP cables have a central cross element which helps maintaining the stability of the cable geometry and reduces the risk of a reduction in performance when bending the cable.", "specs": "• Compliant with all Category 6 cable standardsSupports Class E applicationsCentral cross member maintains geometry and performanceTested up to 350MHzEnhanced reaction-to-fire performance according to CPR classification Cca-s1a,d1,a1 (h/EN50575:2014+A1:2016)DESCRIPTIONAPPLICATIONNexans LANmark-6 cables are the ideal solution for most of today’s network requirements in normal office environments. They are manufactured and tested to the latest Category 6 specifications defined in the International and American cable standards and are designed to meet the quality and performance criteria needed to support all applications up to 250 MHz.10baseT Ethernet100baseTX Fast Ethernet1000baseTX Gigabit Ethernet155 MBit ATM622 MBit ATM1.2 Gbit ATMFuture class E applicationsDESIGNThe LANmark-6 U/UTP cables have a central cross element which helps maintaining the stability of the cable geometry and reduces the risk of a reduction in performance when bending the cable."}$j$::jsonb, 'https://lechantier.ma/en/produits/cablage-electrique/cable-info-u-utp-cat6-nexans') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
