INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('e35a0587-0bb2-5d96-ac2c-5cf8de53f847'::uuid, '0b7329b1-4ec6-53d3-887f-b9537d9f1ab5'::uuid, 'Panel 60-60 Apparent 60W', 'Panel LED 60-60 cm - Modèles encastrés & Apparents - Haute luminosité 60W Optez pour un éclairage moderne , puissant et économique.', 'Lighting', NULL, NULL, 150.0, 'MAD', 'm²', '8 Cartons', 'https://lechantier.ma/uploads/media/4b4537ccfc0d.webp', $j$["https://lechantier.ma/uploads/media/4b4537ccfc0d.webp", "https://lechantier.ma/uploads/media/6799f1c37001.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/eclairage/panel-60-60-apparent-60w", "category_fr": "Luminaire", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 💡 Panel LED 60x60 cm – Modèles encastrés & apparents – Haute luminosité 60WOptez pour un éclairage moderne, puissant et économique avec nos panels LED 60x60, parfaits pour tous vos projets professionnels ou commerciaux.🏭 Vente directe usine – qualité testée, durabilité certifiée, prix imbattables📦 Disponible en grande quantité – idéal pour grossistes, électriciens, installateurs et revendeurs\n• Caractéristiques principales :\n• Puissance : 60W – éclairage intense et homogène\n• Types : Encastrés et Apparents – pour tous types de plafonds\n• Température de couleur : 3000K (blanc chaud) & 6500K (blanc froid)\n• Application : bureaux, écoles, magasins, hôpitaux, entrepôts, administrations…\n• Installation facile – supports et accessoires inclus\n• Technologie LED écoénergétique – jusqu’à 85% d’économie d’énergie\n• Durée de vie prolongée – sans scintillement, sans entretien📍 Stock disponible à Casablanca – Livraison express dans tout le Maroc 🇲🇦", "technical_specifications_original": "• 💡 Panel LED 60x60 cm – Modèles encastrés & apparents – Haute luminosité 60WOptez pour un éclairage moderne, puissant et économique avec nos panels LED 60x60, parfaits pour tous vos projets professionnels ou commerciaux.🏭 Vente directe usine – qualité testée, durabilité certifiée, prix imbattables📦 Disponible en grande quantité – idéal pour grossistes, électriciens, installateurs et revendeurs\n• Caractéristiques principales :\n• Puissance : 60W – éclairage intense et homogène\n• Types : Encastrés et Apparents – pour tous types de plafonds\n• Température de couleur : 3000K (blanc chaud) & 6500K (blanc froid)\n• Application : bureaux, écoles, magasins, hôpitaux, entrepôts, administrations…\n• Installation facile – supports et accessoires inclus\n• Technologie LED écoénergétique – jusqu’à 85% d’économie d’énergie\n• Durée de vie prolongée – sans scintillement, sans entretien📍 Stock disponible à Casablanca – Livraison express dans tout le Maroc 🇲🇦", "specs": "• 💡 Panel LED 60x60 cm – Modèles encastrés & apparents – Haute luminosité 60WOptez pour un éclairage moderne, puissant et économique avec nos panels LED 60x60, parfaits pour tous vos projets professionnels ou commerciaux.🏭 Vente directe usine – qualité testée, durabilité certifiée, prix imbattables📦 Disponible en grande quantité – idéal pour grossistes, électriciens, installateurs et revendeurs\n• Caractéristiques principales :\n• Puissance : 60W – éclairage intense et homogène\n• Types : Encastrés et Apparents – pour tous types de plafonds\n• Température de couleur : 3000K (blanc chaud) & 6500K (blanc froid)\n• Application : bureaux, écoles, magasins, hôpitaux, entrepôts, administrations…\n• Installation facile – supports et accessoires inclus\n• Technologie LED écoénergétique – jusqu’à 85% d’économie d’énergie\n• Durée de vie prolongée – sans scintillement, sans entretien📍 Stock disponible à Casablanca – Livraison express dans tout le Maroc 🇲🇦"}$j$::jsonb, 'https://lechantier.ma/en/produits/eclairage/panel-60-60-apparent-60w') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('eac1fd94-fb9e-5fda-a88f-a4df6398cfde'::uuid, '01ee9428-38a2-5728-9fea-45675b1b219b'::uuid, 'PANEL CARRÉ 60X60 BACKLIT INGELEC', 'Ce panneau LED est le choix idéal si vous recherchez un panneau avec de bonnes caractéristiques et une consommation minimale.', 'Lighting', NULL, NULL, 280.0, 'MAD', 'Pièce', '6 Pièce', 'https://lechantier.ma/uploads/media/ec305f514818.webp', $j$["https://lechantier.ma/uploads/media/ec305f514818.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/eclairage/panel-carre-60x60-backlit-ingelec", "category_fr": "Luminaire", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Il a une utilisation répandue dans les bureaux, les centres commerciaux, les hôpitaux, les entrepôts, les restaurants, les supermarchés, les musées... ainsi que dans les maisons et les résidences.Meilleure efficacité lumineuse : 100lm/WLe panel 60x60 Backlit utilisera des cellules LED avec optique en PMMA pour un meilleur rendu lumineux.Diffuseur en PS sans jaunissement.Le driver LED est sans scintillement (indice < 0.02%)Garantie : 3 ans pour les panels Backlit standards et antiéblouissement.Plus de 30% d’économie d’énergie par rapport aux plafonniers basse luminance à tubes fluorescents.Meilleure optimisation de la lumière : 95% de la lumière est dirigée vers le basLumière uniforme et homogèneDesign moderne pour un montage esthétique et sans contraintes d’encombrementMontage en applique, en plafonnier, encastré, apparent ou suspenduDriver externe pour une meilleure fiabilitéRefroidissement : Les panels sont construits avec un cadre en aluminium et une tôle arrière (bac)", "technical_specifications_original": "• Il a une utilisation répandue dans les bureaux, les centres commerciaux, les hôpitaux, les entrepôts, les restaurants, les supermarchés, les musées... ainsi que dans les maisons et les résidences.Meilleure efficacité lumineuse : 100lm/WLe panel 60x60 Backlit utilisera des cellules LED avec optique en PMMA pour un meilleur rendu lumineux.Diffuseur en PS sans jaunissement.Le driver LED est sans scintillement (indice < 0.02%)Garantie : 3 ans pour les panels Backlit standards et antiéblouissement.Plus de 30% d’économie d’énergie par rapport aux plafonniers basse luminance à tubes fluorescents.Meilleure optimisation de la lumière : 95% de la lumière est dirigée vers le basLumière uniforme et homogèneDesign moderne pour un montage esthétique et sans contraintes d’encombrementMontage en applique, en plafonnier, encastré, apparent ou suspenduDriver externe pour une meilleure fiabilitéRefroidissement : Les panels sont construits avec un cadre en aluminium et une tôle arrière (bac)", "specs": "• Il a une utilisation répandue dans les bureaux, les centres commerciaux, les hôpitaux, les entrepôts, les restaurants, les supermarchés, les musées... ainsi que dans les maisons et les résidences.Meilleure efficacité lumineuse : 100lm/WLe panel 60x60 Backlit utilisera des cellules LED avec optique en PMMA pour un meilleur rendu lumineux.Diffuseur en PS sans jaunissement.Le driver LED est sans scintillement (indice < 0.02%)Garantie : 3 ans pour les panels Backlit standards et antiéblouissement.Plus de 30% d’économie d’énergie par rapport aux plafonniers basse luminance à tubes fluorescents.Meilleure optimisation de la lumière : 95% de la lumière est dirigée vers le basLumière uniforme et homogèneDesign moderne pour un montage esthétique et sans contraintes d’encombrementMontage en applique, en plafonnier, encastré, apparent ou suspenduDriver externe pour une meilleure fiabilitéRefroidissement : Les panels sont construits avec un cadre en aluminium et une tôle arrière (bac)"}$j$::jsonb, 'https://lechantier.ma/en/produits/eclairage/panel-carre-60x60-backlit-ingelec')