INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('d6848001-46d2-538b-9c32-a402b3f6622e'::uuid, '9905df39-f4ef-5a6f-ab9d-9ff7371412a6'::uuid, 'BARRIERE MOSAIQUE', 'Le barriére Mosaique est un élément de mobilier urbain alliant esthétique moderne et robustesse industrielle. Concue en acier galavanisé et protégée par une peinture thérmolaquée.', 'Other', NULL, NULL, 600.0, 'MAD', 'm²', '10 Pièce', 'https://lechantier.ma/uploads/media/ee07ee22fbf1.webp', $j$["https://lechantier.ma/uploads/media/ee07ee22fbf1.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ferronnerie-metallurgie-autres/barriere-mosaique", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Dénomination : Barrière MosaïqueUsage : Mobilier urbain / Sécurisation de zones piétonnes et espaces publicsMatériau principal : Acier galvanisé à chaudFinition : Peinture thermolaquée couleur gris métallisé (autres teintes RAL sur demande)Dimensions standards : Longueur : 3000 mm – Hauteur : 1200 mmSystème de fixation: Sur platine avec ancrage mécanique ou scellement direct dans le solPersonnalisation possible : Dimensions, motifs, teintes RAL, logo ou design spécifique", "technical_specifications_original": "• Dénomination : Barrière MosaïqueUsage : Mobilier urbain / Sécurisation de zones piétonnes et espaces publicsMatériau principal : Acier galvanisé à chaudFinition : Peinture thermolaquée couleur gris métallisé (autres teintes RAL sur demande)Dimensions standards : Longueur : 3000 mm – Hauteur : 1200 mmSystème de fixation: Sur platine avec ancrage mécanique ou scellement direct dans le solPersonnalisation possible : Dimensions, motifs, teintes RAL, logo ou design spécifique", "specs": "• Dénomination : Barrière MosaïqueUsage : Mobilier urbain / Sécurisation de zones piétonnes et espaces publicsMatériau principal : Acier galvanisé à chaudFinition : Peinture thermolaquée couleur gris métallisé (autres teintes RAL sur demande)Dimensions standards : Longueur : 3000 mm – Hauteur : 1200 mmSystème de fixation: Sur platine avec ancrage mécanique ou scellement direct dans le solPersonnalisation possible : Dimensions, motifs, teintes RAL, logo ou design spécifique"}$j$::jsonb, 'https://lechantier.ma/en/produits/ferronnerie-metallurgie-autres/barriere-mosaique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f9fbb34b-1342-56b1-9d52-1392c3c7ad5e'::uuid, '324088ff-17ee-5fa6-a105-9ae0657997e8'::uuid, 'Portail fer forgé double vantaux modèle Royal 3m', 'Portail en fer forgé 2 vantaux, fabrication 100% main. Très solide, avec volutes et décorations. Peinture anti-rouille noire. Sur mesure. 20 ans d''expérience. Installation à Marrakech et région.', 'Other', 'Fabrication artisanale - El Bahiji', NULL, 11000.0, 'MAD', 'm²', NULL, 'https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/logo-1791222884873-480dc8055d02.webp', $j$["https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/logo-1791222884873-480dc8055d02.webp", "https://lechantier.ma/uploads/media/ee07ee22fbf1.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ferronnerie-metallurgie-autres/portail-fer-forge-double-vantaux-modele-royal-3m", "category_fr": "Matériaux de construction", "supplier_matching_status": "partially_matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/ferronnerie-metallurgie-autres/portail-fer-forge-double-vantaux-modele-royal-3m') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('6186c821-1bc1-5171-9721-a5acab23ca8a'::uuid, '6599950d-415c-50aa-93b2-8aeafc7febbc'::uuid, 'Tole en acier galvanisé prelaque blanc', 'Nous proposons des tôles en acier galvanisé prélaqué de haute qualité, idéales pour les travaux de couverture, bardage, hangars, garages, entrepôts et bâtiments industriels. Caractéristiques : * ✔️ Profil : Nervisco * ✔️ Couleur : Blanc * ✔️ Épaisseur : 0,15 mm * ✔️ Largeur utile : 95 cm * ✔️ Longueur : Découpe sur mesure selon vos besoins * ✔️ Résistante à la corrosion et aux intempéries * ✔️ Vente en gros et au détail * ✔️ Stock disponible immédiatement', 'Ironwork & metalwork', 'Tôles', NULL, 50.0, 'MAD', 'm²', '100 Mètre linéaire', 'https://lechantier.ma/uploads/media/20915f58a90c.webp', $j$["https://lechantier.ma/uploads/media/20915f58a90c.webp", "https://lechantier.ma/uploads/media/a2771b7d74b8.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ferronnerie-metallurgie/tole-en-acier-galvanise-prelaque-blanc", "category_fr": "Ironwork & metalwork", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/ferronnerie-metallurgie/tole-en-acier-galvanise-prelaque-blanc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
