INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0a14dac7-bc69-52a7-bdf6-6505700bb1fc'::uuid, '9346c29f-3ff9-5d74-9fdb-039cee3ef96d'::uuid, 'Tole en polyester couvesco translucide', 'Tôle en polyester nervurée légère et résistante, idéale pour toitures et bardages, offrant durabilité, facilité de pose et option de translucidité.', 'Thermal insulation', NULL, NULL, 75.0, 'MAD', 'm²', '1000 Mètre', 'https://lechantier.ma/uploads/media/ceaf24b678a0.webp', $j$["https://lechantier.ma/uploads/media/ceaf24b678a0.webp", "https://lechantier.ma/uploads/media/a49b3c2d8b94.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/isolation-thermique/tole-en-polyester-couvesco-translucide", "category_fr": "Thermal insulation", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Caractéristiques générales :Largeur utile : 0,48 mLongueur : de 2 m à 8 mComposition : Polyester armé de fibresCouleur : Opaque (translucide en option)Propriétés mécaniques et thermiques :Résistance à la traction : 70 N/mm² (ISO 527-4)Module d’élasticité à la traction : 2550 N/mm² (ISO 527-4)Allongement à la rupture : 1,5 % (ISO 527-4)Résistance à la flexion : 100 N/mm² (ISO 14125)Résistance thermique : jusqu’à 80 °CPropriétés thermiques :Coefficient de conductivité thermique (λ) : 0,21 W/mKCoefficient de transmission thermique (U) : 210 W/m²KPoids spécifique : 450 g/m² - 600 g/m²Avantages :Excellente résistance mécanique pour un poids réduitFacilité de découpe et de mise en œuvreTranslucidité optionnelle pour un éclairage naturel", "technical_specifications_original": "• Caractéristiques générales :Largeur utile : 0,48 mLongueur : de 2 m à 8 mComposition : Polyester armé de fibresCouleur : Opaque (translucide en option)Propriétés mécaniques et thermiques :Résistance à la traction : 70 N/mm² (ISO 527-4)Module d’élasticité à la traction : 2550 N/mm² (ISO 527-4)Allongement à la rupture : 1,5 % (ISO 527-4)Résistance à la flexion : 100 N/mm² (ISO 14125)Résistance thermique : jusqu’à 80 °CPropriétés thermiques :Coefficient de conductivité thermique (λ) : 0,21 W/mKCoefficient de transmission thermique (U) : 210 W/m²KPoids spécifique : 450 g/m² - 600 g/m²Avantages :Excellente résistance mécanique pour un poids réduitFacilité de découpe et de mise en œuvreTranslucidité optionnelle pour un éclairage naturel", "specs": "• Caractéristiques générales :Largeur utile : 0,48 mLongueur : de 2 m à 8 mComposition : Polyester armé de fibresCouleur : Opaque (translucide en option)Propriétés mécaniques et thermiques :Résistance à la traction : 70 N/mm² (ISO 527-4)Module d’élasticité à la traction : 2550 N/mm² (ISO 527-4)Allongement à la rupture : 1,5 % (ISO 527-4)Résistance à la flexion : 100 N/mm² (ISO 14125)Résistance thermique : jusqu’à 80 °CPropriétés thermiques :Coefficient de conductivité thermique (λ) : 0,21 W/mKCoefficient de transmission thermique (U) : 210 W/m²KPoids spécifique : 450 g/m² - 600 g/m²Avantages :Excellente résistance mécanique pour un poids réduitFacilité de découpe et de mise en œuvreTranslucidité optionnelle pour un éclairage naturel"}$j$::jsonb, 'https://lechantier.ma/en/produits/isolation-thermique/tole-en-polyester-couvesco-translucide') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
