INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('9e3cc0a6-59cf-5cb3-beed-8b0b0925784d'::uuid, 'd29b8efe-0bb8-5a15-ae3f-655149aacc4b'::uuid, 'POMPE 1 cv ASTRAL VICTORIA PLUS', 'Pompe Filtration Astral VICTORIA Plus 1 cv Mono 16M3/H est une pompe auto-amorçante', 'Pool', NULL, NULL, 3900.0, 'MAD', 'Sac', '1 Sac', 'https://lechantier.ma/uploads/media/8ea79efc4e3a.webp', $j$["https://lechantier.ma/uploads/media/8ea79efc4e3a.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/piscine-piscine/pompe-1-cv-astral-victoria-plus", "category_fr": "Piscine", "supplier_matching_status": "matched", "technical_specifications_detailed": "• La Pompe Filtration Astral VICTORIA Plus 1 cv Mono 16M3/H est une pompe auto-amorçante équipée des nouveaux moteurs Eurotension supportants des variations de tension de ±10% par rapport à la nominale du moteur lui assurant un fonctionnement totalement fiable.Fonctionnement à bas niveau sonore. Robuste Ecrou nouvelle génération pour une ouverture encore plus facile Fonctionnement à faible niveau sonore grâce à ses silent-blocs en gomme Moteur de protection IP55 Panier de préfiltre de grande capacité Tension : 230 V380 v", "technical_specifications_original": "• La Pompe Filtration Astral VICTORIA Plus 1 cv Mono 16M3/H est une pompe auto-amorçante équipée des nouveaux moteurs Eurotension supportants des variations de tension de ±10% par rapport à la nominale du moteur lui assurant un fonctionnement totalement fiable.Fonctionnement à bas niveau sonore. Robuste Ecrou nouvelle génération pour une ouverture encore plus facile Fonctionnement à faible niveau sonore grâce à ses silent-blocs en gomme Moteur de protection IP55 Panier de préfiltre de grande capacité Tension : 230 V380 v", "specs": "• La Pompe Filtration Astral VICTORIA Plus 1 cv Mono 16M3/H est une pompe auto-amorçante équipée des nouveaux moteurs Eurotension supportants des variations de tension de ±10% par rapport à la nominale du moteur lui assurant un fonctionnement totalement fiable.Fonctionnement à bas niveau sonore. Robuste Ecrou nouvelle génération pour une ouverture encore plus facile Fonctionnement à faible niveau sonore grâce à ses silent-blocs en gomme Moteur de protection IP55 Panier de préfiltre de grande capacité Tension : 230 V380 v"}$j$::jsonb, 'https://lechantier.ma/en/produits/piscine-piscine/pompe-1-cv-astral-victoria-plus') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
