INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f13e6453-e535-5d96-9740-6bd7030c88ad'::uuid, '088d8da4-7888-5d58-af9b-b40de64edcaf'::uuid, 'SYSTEME DE SUSPENSION ATLAS', 'La solution parfaite pour la suspension de modules bas lourds.', 'Other', NULL, NULL, 308.0, 'MAD', 'Carton', '2 Cartons', 'https://lechantier.ma/uploads/media/4c20e0f94ca2.webp', $j$["https://lechantier.ma/uploads/media/4c20e0f94ca2.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/quincaillerie-autres/systeme-de-suspension-atlas", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Sécurité maximale dans les charges verticales, anti-chute, usinage et régulation simple.N’interfère pas avec le fonctionnement du tiroir supérieur.Montage industriel simple; pré-montage optionnel pour faciliter le transport.Réglage simple vertical, horizontal et en profondeur.Capacité de charge nominale de 120kg par support. Norme EN 15939 sur structure d’essai B (60kg sur structure d’essai C).", "technical_specifications_original": "• Sécurité maximale dans les charges verticales, anti-chute, usinage et régulation simple.N’interfère pas avec le fonctionnement du tiroir supérieur.Montage industriel simple; pré-montage optionnel pour faciliter le transport.Réglage simple vertical, horizontal et en profondeur.Capacité de charge nominale de 120kg par support. Norme EN 15939 sur structure d’essai B (60kg sur structure d’essai C).", "specs": "• Sécurité maximale dans les charges verticales, anti-chute, usinage et régulation simple.N’interfère pas avec le fonctionnement du tiroir supérieur.Montage industriel simple; pré-montage optionnel pour faciliter le transport.Réglage simple vertical, horizontal et en profondeur.Capacité de charge nominale de 120kg par support. Norme EN 15939 sur structure d’essai B (60kg sur structure d’essai C)."}$j$::jsonb, 'https://lechantier.ma/en/produits/quincaillerie-autres/systeme-de-suspension-atlas') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
