INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2ac92a29-2178-5fdb-b142-dc72d1903197'::uuid, '2fcdd72f-a8f8-53c7-99e7-9b753719cae9'::uuid, 'Poignee intellegent', 'La poignée intelligente est une innovation moderne qui combine design élégant, technologie avancée et fonctionnalité pratique. Conçue pour offrir un accès sécurisé et simplifié', 'Security', NULL, NULL, 2350.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/dc67f7946168.webp', $j$["https://lechantier.ma/uploads/media/dc67f7946168.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/securite/poignee-intellegent", "category_fr": "Security", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔐 Système de verrouillage électronique avec ouverture par empreinte digitale, code, carte RFID ou application mobile.⚙️ Mécanisme silencieux et fluide, garantissant une utilisation confortable au quotidien.🔋 Alimentation par batterie longue durée, avec alerte en cas de faible charge.📱 Connectivité intelligente (Bluetooth ou Wi-Fi) pour contrôle à distance et gestion des accès.🪶 Design ergonomique et moderne, disponible en plusieurs finitions (inox, noir mat, aluminium brossé, etc.).", "technical_specifications_original": "• 🔐 Système de verrouillage électronique avec ouverture par empreinte digitale, code, carte RFID ou application mobile.⚙️ Mécanisme silencieux et fluide, garantissant une utilisation confortable au quotidien.🔋 Alimentation par batterie longue durée, avec alerte en cas de faible charge.📱 Connectivité intelligente (Bluetooth ou Wi-Fi) pour contrôle à distance et gestion des accès.🪶 Design ergonomique et moderne, disponible en plusieurs finitions (inox, noir mat, aluminium brossé, etc.).", "specs": "• 🔐 Système de verrouillage électronique avec ouverture par empreinte digitale, code, carte RFID ou application mobile.⚙️ Mécanisme silencieux et fluide, garantissant une utilisation confortable au quotidien.🔋 Alimentation par batterie longue durée, avec alerte en cas de faible charge.📱 Connectivité intelligente (Bluetooth ou Wi-Fi) pour contrôle à distance et gestion des accès.🪶 Design ergonomique et moderne, disponible en plusieurs finitions (inox, noir mat, aluminium brossé, etc.)."}$j$::jsonb, 'https://lechantier.ma/en/produits/securite/poignee-intellegent') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('513db72d-bec0-5a3c-b693-83e42daa746c'::uuid, '4b0bca9a-90e3-51c9-bd98-70b85cf7293d'::uuid, 'Porte Coup-Feu', 'Nous vous invitons à découvrir nos portes coupe-feu, conçues pour répondre aux normes de sécurité les plus strictes. Elles offrent une résistance au feu allant jusqu''à 120 minutes', 'Security', NULL, NULL, 2200.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/cd3bc81f66dd.webp', $j$["https://lechantier.ma/uploads/media/cd3bc81f66dd.webp", "https://lechantier.ma/uploads/media/53c82241a0d4.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/securite/porte-coup-feu", "category_fr": "Security", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Conception et Matériaux de Haute QualitéVantail & Huisserie : Fabrication robuste en tôle galvanisée pour une durabilité maximale.Finition : Peinture époxy blanche RAL 9010 de série.Isolation Thermique : Isolation haute performance grâce à la laine de roche (165 kg/m³) et à la colle minérale.Sécurité Optimale : Équipée d'un joint intumescent à haute dilatation (positionné entre le vantail et la baie) pour une étanchéité parfaite en cas d'incendie.Équipements Fournis (Prête à l'installation)La porte est livrée assemblée et prête à être posée, incluant :Serrure coupe-feu certifiée CE.Paumelles certifiées CE (disponibles avec ou sans ressorts).Jeu de poignée coupe-feu et cylindre.6 pattes à scellement pour une fixation solide.Résistance et HomologationRésistance au Feu : Disponible en modèles offrant une résistance au feu de 60, 90 ou 120 minutes (selon le modèle sélectionné).Garantie & Conformité : Nos portes sont homologuées et garanties par des essais réalisés dans des laboratoires autorisés, assurant le respect des normes en vigueur.Dimensions et DisponibilitéModèles : Disponible en dimensions standards pour les versions 1 vantail et 2 vantaux.Sur Mesure : Les dimensions spéciales sont disponibles sur commande.", "technical_specifications_original": "• Conception et Matériaux de Haute QualitéVantail & Huisserie : Fabrication robuste en tôle galvanisée pour une durabilité maximale.Finition : Peinture époxy blanche RAL 9010 de série.Isolation Thermique : Isolation haute performance grâce à la laine de roche (165 kg/m³) et à la colle minérale.Sécurité Optimale : Équipée d'un joint intumescent à haute dilatation (positionné entre le vantail et la baie) pour une étanchéité parfaite en cas d'incendie.Équipements Fournis (Prête à l'installation)La porte est livrée assemblée et prête à être posée, incluant :Serrure coupe-feu certifiée CE.Paumelles certifiées CE (disponibles avec ou sans ressorts).Jeu de poignée coupe-feu et cylindre.6 pattes à scellement pour une fixation solide.Résistance et HomologationRésistance au Feu : Disponible en modèles offrant une résistance au feu de 60, 90 ou 120 minutes (selon le modèle sélectionné).Garantie & Conformité : Nos portes sont homologuées et garanties par des essais réalisés dans des laboratoires autorisés, assurant le respect des normes en vigueur.Dimensions et DisponibilitéModèles : Disponible en dimensions standards pour les versions 1 vantail et 2 vantaux.Sur Mesure : Les dimensions spéciales sont disponibles sur commande.", "specs": "• Conception et Matériaux de Haute QualitéVantail & Huisserie : Fabrication robuste en tôle galvanisée pour une durabilité maximale.Finition : Peinture époxy blanche RAL 9010 de série.Isolation Thermique : Isolation haute performance grâce à la laine de roche (165 kg/m³) et à la colle minérale.Sécurité Optimale : Équipée d'un joint intumescent à haute dilatation (positionné entre le vantail et la baie) pour une étanchéité parfaite en cas d'incendie.Équipements Fournis (Prête à l'installation)La porte est livrée assemblée et prête à être posée, incluant :Serrure coupe-feu certifiée CE.Paumelles certifiées CE (disponibles avec ou sans ressorts).Jeu de poignée coupe-feu et cylindre.6 pattes à scellement pour une fixation solide.Résistance et HomologationRésistance au Feu : Disponible en modèles offrant une résistance au feu de 60, 90 ou 120 minutes (selon le modèle sélectionné).Garantie & Conformité : Nos portes sont homologuées et garanties par des essais réalisés dans des laboratoires autorisés, assurant le respect des normes en vigueur.Dimensions et DisponibilitéModèles : Disponible en dimensions standards pour les versions 1 vantail et 2 vantaux.Sur Mesure : Les dimensions spéciales sont disponibles sur commande."}$j$::jsonb, 'https://lechantier.ma/en/produits/securite/porte-coup-feu') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('ca1d4d0a-e0d9-56bd-b943-050b0d3c2e8a'::uuid, '4b0bca9a-90e3-51c9-bd98-70b85cf7293d'::uuid, 'Quincaillerie', 'HAVA HARD TRADE propose une gamme complète de solutions de verrouillage et d''accessoires pour portes, alliant sécurité, design et technologie.', 'Security', NULL, NULL, 50.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/3343a9a908c0.webp', $j$["https://lechantier.ma/uploads/media/3343a9a908c0.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/securite/quincaillerie", "category_fr": "Security", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Nos produits couvrent tous les besoins des professionnels du bâtiment :Serrures mécaniques et électroniques,Contrôle d’accès intelligent,Ferme-portes et barres antipaniques,Poignées, cylindres, paumelles et accessoires haut de gamme.", "technical_specifications_original": "• Nos produits couvrent tous les besoins des professionnels du bâtiment :Serrures mécaniques et électroniques,Contrôle d’accès intelligent,Ferme-portes et barres antipaniques,Poignées, cylindres, paumelles et accessoires haut de gamme.", "specs": "• Nos produits couvrent tous les besoins des professionnels du bâtiment :Serrures mécaniques et électroniques,Contrôle d’accès intelligent,Ferme-portes et barres antipaniques,Poignées, cylindres, paumelles et accessoires haut de gamme."}$j$::jsonb, 'https://lechantier.ma/en/produits/securite/quincaillerie') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('01254942-5752-53ea-8f75-a41bbc843fde'::uuid, '6599950d-415c-50aa-93b2-8aeafc7febbc'::uuid, 'TOLE en acier Galvanisé Prelaqué', 'Toles en acier galvanisé d''épaisseur 0,4mm conçues pour le Bardage ,aillants solidité ,durabilité disponible en deux profils effet brique et Nervisco disponible en rouge et blanc', 'Metal sheets', NULL, NULL, 77.0, 'MAD', 'm²', '100 Mètre', 'https://lechantier.ma/uploads/media/6c77ebc10d45.webp', $j$["https://lechantier.ma/uploads/media/6c77ebc10d45.webp", "https://lechantier.ma/uploads/media/ee63b2eb9570.webp", "https://lechantier.ma/uploads/media/a1aa292025d3.webp", "https://lechantier.ma/uploads/media/f9d657b78974.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/toles/tole-en-acier-galvanise-prelaque", "category_fr": "Metal sheets", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Epaisseur 0,4mmLargeur 1mlongueur :sur commande", "technical_specifications_original": "• Epaisseur 0,4mmLargeur 1mlongueur :sur commande", "specs": "• Epaisseur 0,4mmLargeur 1mlongueur :sur commande"}$j$::jsonb, 'https://lechantier.ma/en/produits/toles/tole-en-acier-galvanise-prelaque') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('79a37506-da75-5773-8358-9f6cfcc19381'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Les tuyaux en polyéthylène (PE)', 'Les tuyaux en polyéthylène (PE) sont des conduites souples ou semi-rigides utilisées principalement pour l''irrigation agricole,', 'Pipes', NULL, NULL, 500.0, 'MAD', 'm²', '200 mètres', 'https://lechantier.ma/uploads/media/4a45d0b1d052.webp', $j$["https://lechantier.ma/uploads/media/4a45d0b1d052.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/tuyau/les-tuyaux-en-polyethylene-pe", "category_fr": "Pipes", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Voici un paragraphe rédigé à partir des caractéristiques techniques des tuyaux en polyéthylène :Les tuyaux en polyéthylène sont fabriqués à partir de polyéthylène basse densité (PEBD) ou haute densité (PEHD), selon les besoins en souplesse et en résistance à la pression. Ils sont disponibles dans une large gamme de diamètres extérieurs standards, allant de 16 mm à 63 mm, ce qui permet de les adapter à différents types de réseaux d'irrigation ou d'adduction d’eau. Ils supportent des pressions nominales (PN) variables, généralement de PN4 à PN16, en fonction de l’application (basse ou haute pression). Ces tuyaux sont conçus pour fonctionner dans une plage de température de service allant de -10°C à +60°C, ce qui les rend adaptés à une utilisation en extérieur, même en conditions climatiques variées. Ils sont commercialisés sous forme de rouleaux de 25, 50, 100 ou 200 mètres, ou en barres droites, selon les exigences du chantier ou de l’installation.", "technical_specifications_original": "• Voici un paragraphe rédigé à partir des caractéristiques techniques des tuyaux en polyéthylène :Les tuyaux en polyéthylène sont fabriqués à partir de polyéthylène basse densité (PEBD) ou haute densité (PEHD), selon les besoins en souplesse et en résistance à la pression. Ils sont disponibles dans une large gamme de diamètres extérieurs standards, allant de 16 mm à 63 mm, ce qui permet de les adapter à différents types de réseaux d'irrigation ou d'adduction d’eau. Ils supportent des pressions nominales (PN) variables, généralement de PN4 à PN16, en fonction de l’application (basse ou haute pression). Ces tuyaux sont conçus pour fonctionner dans une plage de température de service allant de -10°C à +60°C, ce qui les rend adaptés à une utilisation en extérieur, même en conditions climatiques variées. Ils sont commercialisés sous forme de rouleaux de 25, 50, 100 ou 200 mètres, ou en barres droites, selon les exigences du chantier ou de l’installation.", "specs": "• Voici un paragraphe rédigé à partir des caractéristiques techniques des tuyaux en polyéthylène :Les tuyaux en polyéthylène sont fabriqués à partir de polyéthylène basse densité (PEBD) ou haute densité (PEHD), selon les besoins en souplesse et en résistance à la pression. Ils sont disponibles dans une large gamme de diamètres extérieurs standards, allant de 16 mm à 63 mm, ce qui permet de les adapter à différents types de réseaux d'irrigation ou d'adduction d’eau. Ils supportent des pressions nominales (PN) variables, généralement de PN4 à PN16, en fonction de l’application (basse ou haute pression). Ces tuyaux sont conçus pour fonctionner dans une plage de température de service allant de -10°C à +60°C, ce qui les rend adaptés à une utilisation en extérieur, même en conditions climatiques variées. Ils sont commercialisés sous forme de rouleaux de 25, 50, 100 ou 200 mètres, ou en barres droites, selon les exigences du chantier ou de l’installation."}$j$::jsonb, 'https://lechantier.ma/en/produits/tuyau/les-tuyaux-en-polyethylene-pe') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
